  example (nth_value([5, 6, 7], 2) == 7)
{
  match xs { [] => 0 [h, ..t] => if (i == 0) then h else nth_value(t, (i - 1)) }
}

fn nth(xs: List[Int], i: Int) -> Option[Int]
  requires (i >= 0)
  ensures (((i < len(xs)) and (result == Some(nth_value(xs, i)))) or ((i >= len(xs)) and (result == None)))
  effects pure
  example (nth([5, 6, 7], 1) == Some(6))
  example (nth([5, 6, 7], 3) == None)
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else nth(t, (i - 1)) }
}

